'use strict';

// MAIN //

/**
* Returns defaults.
*
* @private
* @param {string} direction - legend direction
* @returns {Object} default options
*
* @example
* var o = defaults( 'vertical' );
* // returns {...}
*/
function defaults( direction ) {
	return {
		// Boolean indicating whether to include ARIA attributes in SVG output:
		'aria': true,

		// Number of columns in which to arrange symbol legend entries:
		'columns': ( direction === 'horizontal' ) ? 0 : 1,

		// Direction of the legend:
		'direction': 'vertical',

		// Grid alignment for legend entries:
		'gridAlign': 'each',

		// Vertical text baseline of legend labels:
		'labelBaseline': 'alphabetic',

		// Strategy for resolving overlapping legend labels:
		'labelOverlap': true,

		// Minimum separation between label bounding boxes for non-overlapping:
		'labelSeparation': 0,

		// Legend orientation:
		'orient': 'right',

		// Stroke dash for legend symbols:
		'symbolDash': [],

		// Legend title:
		'title': [ '' ],

		// Anchor position for placing a legend title:
		'titleAnchor': null,

		// Vertical text baseline of the legend title:
		'titleBaseline': 'alphabetic',

		// Orientation of the legend title:
		'titleOrient': 'top',

		// Integer z-index indicating the layering of the legend group relative to other axis, mark, and legend groups:
		'zindex': 0
	};
}


// EXPORTS //

module.exports = defaults;
